  function initAudio(){window.GardenMusic?.start();if(!audio){const A=window.AudioContext||window.webkitAudioContext;if(!A)return;audio=new A();master=audio.createGain();master.gain.value=.23;master.connect(audio.destination);}if(audio.state==='suspended')audio.resume().catch(()=>{});}
  function note(f=523,d=.5,v=.17,delay=0){if(!sound||!audio)return;const t=audio.currentTime+delay;[1,2,3].forEach((h,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=f*h;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v/(1+i*4),t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(master);o.start(t);o.stop(t+d+.02);});}
  function sfx(k){if(k==='seal'||k==='win')[392,523,659,784,1047].forEach((f,i)=>note(f,1.3,.15,i*.1));else if(k==='hit'){note(147,.35,.2);note(156,.3,.1);}else if(k==='fan'){note(196,.18,.09);note(392,.3,.08,.04);}else if(k==='dew')note(659,.5,.14);else if(k==='dash')note(440,.25,.11);else note(523,.3,.12);}
