    const seals=maze.shrines.filter(s=>s.solved).length, explored=exploration(),score=Math.max(0,Math.round(seals*550+explored*4+Math.max(time,0)*5+p.dew*8+killCount*12-hints*45-damageCount*60));
    $('result-kicker').textContent=win?'踏 花 而 归':'春 光 待 续';$('result-title').textContent=win?'三印归扇，春门为你开。':reason==='health'?'花容暂歇，归路尚在。':'春光已尽，此园未完。';
