  $('heal').onclick=heal;
  $('bloom').onclick=bloom;
  function discover(){const cx=Math.floor(p.x/T),cy=Math.floor(p.y/T);for(let dy=-4;dy<=4;dy++)for(let dx=-4;dx<=4;dx++)if(dx*dx+dy*dy<=18){const x=cx+dx,y=cy+dy;if(x>=0&&x<maze.cols&&y>=0&&y<maze.rows)seen.add(y*maze.cols+x);}}
