    $('interact').hidden=!interactable||state!=='playing';if(interactable){const e=interactable;$('interact-label').textContent=e.kind==='shrine'?e.o.solved?e.o.name+' · 花印已得':'入'+e.o.name+' · 解机关':e.kind==='exit'?'月洞门 · 出园':e.kind==='fortune'?'签亭 · 选一阵春风':'花扉 · 捷径（5露）';}
    canvas.dataset.state=state;canvas.dataset.cell=String(p.cell);canvas.dataset.seed=String(seed);canvas.dataset.moving=String(!!p.move);canvas.dataset.seals=String(n);canvas.dataset.health=String(p.hp);canvas.dataset.time=String(Math.ceil(time));canvas.dataset.energy=String(Math.floor(p.energy));drawMap($('minimap'));if(state==='map')drawMap($('large-map'),true);
